use vstd::prelude::*;

verus! {
    // where_fn: element‐wise selection between two f32 arrays based on a boolean mask
    fn where_fn(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> (result: Vec<f32>)
        requires
            // All inputs have the same length
            condition.len() == x.len(),
            x.len() == y.len(),
        ensures
            // The result has the same length
            result.len() == condition.len(),
            // And for each index i, we pick x[i] if condition[i] is true,
            // otherwise y[i].
            forall |i: usize|
                i < result.len() ==>
                    if condition[i] {
                        result[i] == x[i]
                    } else {
                        result[i] == y[i]
                    },
    {
        let n = condition.len();
        let mut result: Vec<f32> = Vec::new();
        let mut idx: usize = 0;

        // Build up result one element at a time
        while idx < n
            invariant
                // 0 ≤ idx ≤ n
                idx <= n,
                // We've pushed exactly idx elements so far
                result.len() == idx,
                // And for all j < idx, result[j] satisfies the selection property
                forall |j: usize|
                    j < idx ==>
                        if condition[j] {
                            result[j] == x[j]
                        } else {
                            result[j] == y[j]
                        },
            decreases n - idx,
        {
            if condition[idx] {
                result.push(x[idx]);
            } else {
                result.push(y[idx]);
            }
            idx += 1;
        }

        result
    }
}

